      if (settled) return;
      settled = true;
      resolve({ opened, frames, close: () => { try { ws.close(); } catch (e) { /* closed */ } } });
    };
    try {
      ws = new WebSocket(url, { headers: cookie ? { cookie } : {} });
    } catch (e) {
      return done(false);
