      return json(200, {
        access_token: access,
        token_type: 'Bearer',
        expires_in: 3600,
        id_token: signJwt({ iss: ISSUER, aud: CLIENT_ID, sub: u.sub, iat: now, exp: now + 3600, nonce: entry.nonce, name: u.name, email: u.email, workspaces: u.workspaces }),
