import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { claim, release, setStatus } from '../src/lib/conversations.ts';
import { cols } from '../src/db.ts';
import { wipe, close } from './helpers.ts';

before(wipe);
after(async () => {
  await wipe();
  await close();
});

test('six agents claiming at once: exactly one wins', async () => {
  const agents = Array.from({ length: 6 }, (_, i) => `agent_${i}`);
  const results = await Promise.all(agents.map((a) => claim('ws_acme', '+14155550101', a)));
  const winners = results.filter((r) => r === 'claimed');
  assert.equal(winners.length, 1);
  assert.equal(results.filter((r) => r === 'taken').length, 5);

  const { convs } = await cols();
  const row = await convs.findOne({ ws: 'ws_acme', contact: '+14155550101' });
  assert.equal(row?.assignee, agents[results.indexOf('claimed')]);
});

test('the holder claiming again is not an error', async () => {
  assert.equal(await claim('ws_acme', '+14155550102', 'a'), 'claimed');
  assert.equal(await claim('ws_acme', '+14155550102', 'a'), 'already');
  assert.equal(await claim('ws_acme', '+14155550102', 'b'), 'taken');
});

test('claiming a contact that never wrote creates the conversation', async () => {
  assert.equal(await claim('ws_globex', '+442079460299', 'x'), 'claimed');
  const { convs } = await cols();
  assert.equal((await convs.findOne({ ws: 'ws_globex', contact: '+442079460299' }))?.status, 'open');
});

test('same contact in two workspaces is two conversations', async () => {
  assert.equal(await claim('ws_acme', '+10000000001', 'a'), 'claimed');
  assert.equal(await claim('ws_globex', '+10000000001', 'b'), 'claimed');
});

test('only the holder or an admin can release', async () => {
  await claim('ws_acme', '+14155550103', 'a');
  assert.equal(await release('ws_acme', '+14155550103', 'b', false), false);
  assert.equal(await release('ws_acme', '+14155550103', 'b', true), true);
  assert.equal(await claim('ws_acme', '+14155550103', 'b'), 'claimed');
});

test('close and reopen only report a change when there is one', async () => {
  await claim('ws_acme', '+14155550104', 'a');
  assert.equal(await setStatus('ws_acme', '+14155550104', 'open'), false);
  assert.equal(await setStatus('ws_acme', '+14155550104', 'closed'), true);
  assert.equal(await setStatus('ws_acme', '+14155550104', 'closed'), false);
  assert.equal(await setStatus('ws_acme', '+14155550104', 'open'), true);
});
EOF
cat > test/frames.test.ts <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { addFrame, framesAfter, lastSeq } from '../src/lib/frames.ts';
import { wipe, close } from './helpers.ts';

before(wipe);
after(async () => {
  await wipe();
  await close();
});

test('concurrent frames get gap-free, unique seqs', async () => {
  await Promise.all(Array.from({ length: 40 }, (_, i) => addFrame('ws_acme', `k${i}`, { type: 'x', n: i })));
  const all = await framesAfter('ws_acme', 0, 100);
  assert.deepEqual(
    all.map((f) => f.seq),
    Array.from({ length: 40 }, (_, i) => i + 1),
  );
});

test('the same key written many times at once is one frame', async () => {
  const before = await lastSeq('ws_globex');
  await Promise.all(Array.from({ length: 10 }, () => addFrame('ws_globex', 'same', { type: 'x' })));
  assert.equal((await lastSeq('ws_globex')) - before, 1);
});

test('framesAfter only returns what comes after, in order', async () => {
  const rest = await framesAfter('ws_acme', 35);
  assert.deepEqual(rest.map((f) => f.seq), [36, 37, 38, 39, 40]);
});

test('workspaces count their own seq', async () => {
  assert.equal((await framesAfter('ws_globex', 0))[0].seq, 1);
});
EOF
cat > test/ratelimit.test.ts <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { acquire, pause, refund } from '../src/lib/ratelimit.ts';
import { getRedis } from '../src/redis.ts';

const ws = 'ws_test_rl';
const clear = () => getRedis().del(`sb:rl:${ws}`, `sb:cool:${ws}`);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

before(clear);
after(async () => {
  await clear();
  getRedis().disconnect();
});

test('a burst is capped below what the provider allows', async () => {
  let granted = 0;
  for (let i = 0; i < 20; i++) if (await acquire(ws)) granted++;
  assert.ok(granted >= 5 && granted <= 7, `granted ${granted}`);
});

test('tokens come back over time', async () => {
  await sleep(600);
  assert.equal(await acquire(ws), true);
});

test('a refund gives a token back', async () => {
  await clear();
  for (let i = 0; i < 20; i++) await acquire(ws);
  assert.equal(await acquire(ws), false);
  await refund(ws);
  assert.equal(await acquire(ws), true);
});

test('a pause blocks everyone until it ends', async () => {
  await clear();
  await pause(ws, 300);
  assert.equal(await acquire(ws), false);
  await sleep(350);
  assert.equal(await acquire(ws), true);
});

test('a short pause does not shorten a longer one', async () => {
  await clear();
  await pause(ws, 2000);
  await pause(ws, 100);
  const left = await getRedis().pttl(`sb:cool:${ws}`);
  assert.ok(left > 1500, `ttl ${left}`);
});
EOF
