import * as c from '/Users/apple/Desktop/repo-new/switchboard/scaffold/web/src/crypto.ts';

const BASE = 'http://localhost:4000';
async function login(sub: string) {
  const jar: Record<string, string> = {};
  const keep = (r: Response) => r.headers.getSetCookie().forEach((x) => { const [p] = x.split(';'); const i = p.indexOf('='); jar[p.slice(0, i)] = p.slice(i + 1); });
  const ck = () => Object.entries(jar).map(([k, v]) => `${k}=${v}`).join('; ');
  const s = await fetch(`${BASE}/auth/login`, { redirect: 'manual' }); keep(s);
  const p = await fetch(`${s.headers.get('location')}&login=${sub}`, { redirect: 'manual' });
  const cb = await fetch(p.headers.get('location')!, { redirect: 'manual', headers: { cookie: ck() } }); keep(cb);
  return (method: string, path: string, body?: unknown) => fetch(BASE + path, { method, headers: { 'content-type': 'application/json', cookie: ck() }, body: body === undefined ? undefined : JSON.stringify(body) });
}
const ok = (cond: boolean, msg: string) => { console.log(cond ? 'ok  ' : 'FAIL', msg); if (!cond) process.exitCode = 1; };

const WS = 'ws_acme', CONTACT = '+14155550101';
const asha = await login('u_asha'), ben = await login('u_ben');
const aKeys = await c.generateKeyPair(), bKeys = await c.generateKeyPair();
const aPub = await c.exportPublicKey(aKeys.publicKey), bPub = await c.exportPublicKey(bKeys.publicKey);

ok((await asha('PUT', '/api/keys', { workspace: WS, publicKey: aPub })).status === 200, 'asha registers her public key');
ok((await ben('PUT', '/api/keys', { workspace: WS, publicKey: bPub })).status === 200, 'ben registers his public key');

const K = await c.generateWorkspaceKey();
const wrappedForAsha = await c.wrapWorkspaceKey(K, aKeys.privateKey, aPub);
ok((await asha('POST', `/api/workspaces/${WS}/keyring`, { wrappedKey: wrappedForAsha })).status === 201, 'asha creates the workspace key');
ok((await ben('POST', `/api/workspaces/${WS}/keyring`, { wrappedKey: wrappedForAsha })).status === 409, 'ben cannot create a second one');

const wrappedForBen = await c.wrapWorkspaceKey(K, aKeys.privateKey, bPub);
ok((await ben('PUT', `/api/workspaces/${WS}/keys/u_asha`, { wrappedKey: wrappedForBen })).status === 403, 'ben cannot share a key he does not hold');
ok((await asha('PUT', `/api/workspaces/${WS}/keys/u_ben`, { wrappedKey: wrappedForBen })).status === 200, 'asha shares the key with ben');

const text = 'customer is unhappy, refund approved ✓';
const aad = c.noteAad(WS, CONTACT, 'u_asha');
const enc = await c.encryptNote(K, text, aad);
ok((await asha('POST', `/api/conversations/${encodeURIComponent(CONTACT)}/notes`, { workspace: WS, ...enc })).status === 201, 'asha posts an encrypted note');

const state = (await (await ben('GET', `/api/workspaces/${WS}/keys`)).json()) as any;
const ashaPublic = state.members.find((m: any) => m.sub === state.mine.wrappedBy).publicKey;
const benK = await c.unwrapWorkspaceKey(state.mine.wrappedKey, bKeys.privateKey, ashaPublic);
const list = (await (await ben('GET', `/api/conversations/${encodeURIComponent(CONTACT)}/notes?workspace=${WS}`)).json()) as any;
const n = list.notes[0];
ok(await c.decryptNote(benK, n.ciphertext, n.iv, c.noteAad(WS, n.author === 'u_asha' ? WS : WS, CONTACT, n.author)).then((t: string) => t === text).catch(() => false), 'ben decrypts the note');

ok(!JSON.stringify(list).includes('refund'), 'the server response contains no plaintext');
const elsewhere = await c.decryptNote(benK, n.ciphertext, n.iv, c.noteAad(WS, '+14155550102', n.author)).then(() => true).catch(() => false);
ok(!elsewhere, 'the same note does not decrypt as another conversation');
const otherKey = await c.generateWorkspaceKey();
const wrong = await c.decryptNote(otherKey, n.ciphertext, n.iv, c.noteAad(WS, CONTACT, n.author)).then(() => true).catch(() => false);
ok(!wrong, 'the wrong workspace key cannot read it');
EOF
