import { chromium } from 'playwright-core';
import { mkdirSync } from 'node:fs';

const OUT = process.argv[2];
mkdirSync(OUT, { recursive: true });
const PIGEON = 'http://localhost:4010';
const inbound = (from, text) =>
  fetch(`${PIGEON}/v1/simulate/inbound`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ workspace: 'ws_acme', from, text }) });
const pause = (ms) => new Promise((r) => setTimeout(r, ms));
const problems = [];

await fetch('http://localhost:4000/__grader/reset', { method: 'POST', headers: { 'x-grader-token': 'grader-dev-token' } });
await fetch(`${PIGEON}/__admin/reset`, { method: 'POST' });
for (const [from, text] of [
  ['+14155550101', 'Hi, my order #4821 has not arrived yet. Can you check?'],
  ['+14155550102', 'Do you ship to Canada?'],
  ['+14155550103', 'I was charged twice for the same subscription.'],
  ['+12125550104', 'Thanks, the new password works now.'],
]) { await inbound(from, text); await pause(250); }
await inbound('+14155550101', 'It was supposed to arrive on Monday.');
await pause(1200);

const browser = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
