import { readFileSync, writeFileSync } from 'node:fs';
const [, , input, output, title] = process.argv;
const lines = readFileSync(input, 'utf8').split('
').filter(Boolean);
const fence = (s) => '```
' + String(s).replace(/```/g, '`​``') + '
```';
const textOf = (c) => (typeof c === 'string' ? c : Array.isArray(c) ? c.map((x) => (x.type === 'text' ? x.text : x.type === 'image' ? '[image omitted: binary data, see the .jsonl]' : JSON.stringify(x))).join('
') : JSON.stringify(c));
let out = `# ${title}

Plain rendering of the adjacent \`.jsonl\` file, which is the unedited export. Nothing is removed except binary image data.

`;
for (const line of lines) {
  let e; try { e = JSON.parse(line); } catch { continue; }
  if (e.type !== 'user' && e.type !== 'assistant') continue;
  const m = e.message; if (!m) continue;
  out += `
---

## ${m.role ?? e.type}${e.timestamp ? '  
' + e.timestamp : ''}

`;
  const blocks = typeof m.content === 'string' ? [{ type: 'text', text: m.content }] : m.content ?? [];
  for (const b of blocks) {
    if (b.type === 'text') out += b.text + '

';
    else if (b.type === 'thinking') out += `_thinking_

${b.thinking ?? ''}

`;
    else if (b.type === 'tool_use') out += `**tool call: ${b.name}**

${fence(JSON.stringify(b.input, null, 2))}

`;
    else if (b.type === 'tool_result') out += `**tool result**

${fence(textOf(b.content))}

`;
    else if (b.type === 'image') out += '[image omitted: binary data, see the .jsonl]

';
    else out += fence(JSON.stringify(b)) + '

';
  }
}
writeFileSync(output, out);
console.log(output, (out.length / 1e6).toFixed(1) + ' MB');
EOF
