import { chromium } from 'playwright-core';
const OUT = '/tmp/shots/billing';
import { mkdirSync } from 'node:fs'; mkdirSync(OUT, { recursive: true });
const pause = (ms) => new Promise((r) => setTimeout(r, ms));
await fetch('http://localhost:4000/__grader/reset', { method: 'POST', headers: { 'x-grader-token': 'grader-dev-token' } });
const browser = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
const login = async (name) => {
  const ctx = await browser.newContext({ viewport: { width: 1360, height: 860 } });
  const page = await ctx.newPage();
  page.on('response', (r) => { if (r.status() >= 400 && !/\/api\/me/.test(r.url())) console.log('   HTTP', r.status(), r.request().method(), r.url().replace(/http:\/\/localhost:\d+/, '')); });
  await page.goto('http://localhost:5173');
  await page.getByRole('link', { name: /Sign in/ }).click();
  await page.waitForURL(/localhost:4020/);
  await page.getByRole('link', { name }).click();
  await page.waitForURL(/localhost:5173/);
  await page.getByRole('button', { name: /Account menu/ }).waitFor();
  return page;
};
const step = async (n, fn) => { try { await fn(); console.log('ok  ', n); } catch (e) { console.log('FAIL', n, String(e.message).split('\n')[0]); } };

const ben = await login('Ben Ortiz');
await step('agent has no Billing entry', async () => {
  const n = await ben.getByRole('button', { name: 'Billing' }).count();
  if (n) throw new Error('Billing visible to agent');
  const api = await ben.evaluate(async () => (await fetch('/api/billing?workspace=ws_acme')).status);
  if (api !== 403) throw new Error('agent API status ' + api);
});

const asha = await login('Asha Rao');
await step('admin opens billing (free trial)', async () => {
  await asha.getByRole('button', { name: 'Billing' }).first().click();
  await asha.getByText(/free trial/i).first().waitFor({ timeout: 8000 });
  await pause(400);
  await asha.screenshot({ path: `${OUT}/01-trial.png` });
});
await step('subscribe with 4242 card', async () => {
  await asha.getByLabel('Card number').fill('4242 4242 4242 4242');
  await asha.getByLabel(/Expiry/).fill('12/30');
  await asha.getByLabel('Security code').fill('123');
  await asha.screenshot({ path: `${OUT}/02-form.png` });
  await asha.getByRole('button', { name: /^Pay|Subscribe/ }).first().click();
  await asha.getByText(/active/i).first().waitFor({ timeout: 15000 });
  await pause(500);
  await asha.screenshot({ path: `${OUT}/03-active.png` });
});
await step('change seats', async () => {
  const stepper = asha.getByRole('button', { name: /increase|more|\+/i }).first();
  await stepper.click();
  await asha.getByRole('button', { name: /Update seats/ }).click();
  await pause(1500);
  await asha.screenshot({ path: `${OUT}/04-seats.png` });
});
await browser.close();
EOF
